import urllib.request, io
from PIL import Image

def avg(im):
    im = im.resize((64,36))
    px = list(im.get_flattened_data() if hasattr(im,'get_flattened_data') else im.getdata())
    n = len(px)
    return tuple(round(sum(p[i] for p in px)/n) for i in range(3))

def load(url):
    data = urllib.request.urlopen(urllib.request.Request(url, headers={'User-Agent':'Mozilla/5.0'}), timeout=15).read()
    return Image.open(io.BytesIO(data)).convert('RGB')

cands = {
 'A Believer':'7wtfhZwyrcc','B Faded':'60ItHLz5WEA','C Heathens':'UprcpdwuwCg',
 'D HymnWeekend':'YykjpeuMNEk','E Numb':'kXYiU_JCYtU','F Rockabye':'papuvlVeZg8',
 'G StressedOut':'pXRviuL6vMY','H Thunder':'fKopy74weus','I BlankSpace':'e-ORhEE9VVg',
 'J Chandelier':'2vjPBrBU-TM'}
for label, vid in cands.items():
    out=[]
    for kind in ['mqdefault','maxresdefault','maxres1','maxres2','maxres3']:
        url=f'https://i.ytimg.com/vi/{vid}/{kind}.jpg'
        try:
            im=load(url)
            if im.size[0]/im.size[1] < 1.7:  # padded, crop bars
                im = im.crop((0,int(im.size[1]*0.125),im.size[0],int(im.size[1]*0.875)))
            out.append(f'{kind}={avg(im)}')
        except Exception:
            out.append(f'{kind}=--')
    print(label.ljust(14), ' | '.join(out))

# barcode reference values
bc = Image.open('barcode.png').convert('RGB')
w,h = bc.size
px = bc.load()
cols=[]
for x in range(w):
    r=g=b=0
    for y in range(h):
        p=px[x,y]; r+=p[0]; g+=p[1]; b+=p[2]
    cols.append((r/h,g/h,b/h))
import statistics
allpx=[]
for x in range(w):
    for y in range(0,h,4):
        allpx.append(px[x,y])
n=len(allpx)
overall=tuple(round(sum(p[i] for p in allpx)/n) for i in range(3))
print('BARCODE overall avg:', overall)
for frac,label in [(0.25,'25%'),(0.5,'50%'),(0.75,'75%')]:
    x=int(frac*w)
    print(f'BARCODE {label} (x={x}):', tuple(round(c) for c in cols[x]))
EOF

