import urllib.request
from PIL import Image

def load(url):
    data = urllib.request.urlopen(urllib.request.Request(url, headers={'User-Agent':'Mozilla/5.0'}), timeout=15).read()
    return Image.open(io.BytesIO(data)).convert('RGB')

import io
cands = {
 'believer':'7wtfhZwyrcc','faded':'60ItHLz5WEA','heathens':'UprcpdwuwCg',
 'numb':'kXYiU_JCYtU','stressedout':'pXRviuL6vMY','thunder':'fKopy74weus',
 'chandelier':'2vjPBrBU-TM','hymn':'YykjpeuMNEk','rockabye':'papuvlVeZg8','blank':'e-ORhEE9VVg'}
for label, vid in cands.items():
    tiles=[]
    for kind in ['1','2','3']:
        try:
            im = load(f'https://i.ytimg.com/vi/{vid}/hq{kind}.jpg')
