import urllib.request, io, json
from PIL import Image

def load(url):
    data = urllib.request.urlopen(urllib.request.Request(url, headers={'User-Agent':'Mozilla/5.0'}), timeout=15).read()
    return Image.open(io.BytesIO(data)).convert('RGB')

for vid in ['JFmN9ULMPms','tbjcSZTxvyw']:
    # verify title
    try:
        d = json.load(urllib.request.urlopen(f'https://www.youtube.com/oembed?url=https://www.youtube.com/watch?v={vid}&format=json', timeout=10))
        print(vid, d['title'])
    except Exception as e:
        print(vid, 'oembed fail')
    tiles=[]
    for kind in ['maxres1','maxres2','maxres3']:
        try:
            im = load(f'https://i.ytimg.com/vi/{vid}/{kind}.jpg')
            tiles.append(im)
        except Exception as e:
            tiles.append(Image.new('RGB',(100,100),(255,0,255)))
            print(kind,'fail',e)
    if tiles:
        w = max(t.size[0] for t in tiles)
        sheet = Image.new('RGB',(sum(t.size[0] for t in tiles), max(t.size[1] for t in tiles)),(20,20,20))
        x=0
        for t in tiles:
            sheet.paste(t,(x,0)); x+=t.size[0]
        sheet.save(f'frames/cal_{vid}.jpg', quality=90)
        print('saved', [t.size for t in tiles])
EOF

